SELECT s.Name, s.Location
FROM stadium s
WHERE EXISTS (
    SELECT 1 FROM concert c1 WHERE c1.Stadium_ID = s.Stadium_ID AND c1.Year = '2014'
)
AND EXISTS (
    SELECT 1 FROM concert c2 WHERE c2.Stadium_ID = s.Stadium_ID AND c2.Year = '2015'
);

SELECT Fname
FROM Student
WHERE StuID IN (
    SELECT StuID FROM Has_Pet JOIN Pets ON Has_Pet.PetID = Pets.PetID WHERE PetType = 'cat'
)
AND StuID IN (
    SELECT StuID FROM Has_Pet JOIN Pets ON Has_Pet.PetID = Pets.PetID WHERE PetType = 'dog'
);

SELECT PetType, AVG(pet_age) AS avg_age, MAX(pet_age) AS max_age
FROM Pets
GROUP BY PetType;

SELECT DISTINCT a.Airline
FROM airlines a
WHERE EXISTS (
    SELECT 1 FROM flights f WHERE f.Airline = a.uid AND f.SourceAirport = 'CVO'
)
AND NOT EXISTS (
    SELECT 1 FROM flights f WHERE f.Airline = a.uid AND f.SourceAirport = 'APG'
);

SELECT Name, Location, District
FROM shop
ORDER BY Number_products DESC;

SELECT Name
FROM shop
WHERE Number_products > (SELECT AVG(Number_products) FROM shop);

SELECT Name
        FROM employee
        WHERE Employee_ID NOT IN (SELECT Employee_ID FROM evaluation);

SELECT Document_ID FROM Paragraphs WHERE Paragraph_Text LIKE '%Brazil%'
INTERSECT
SELECT Document_ID FROM Paragraphs WHERE Paragraph_Text LIKE '%Ireland%';

SELECT COUNT(*) FROM battle b
LEFT JOIN ship s ON b.id = s.lost_in_battle AND s.tonnage = '225'
WHERE s.id IS NULL;

SELECT b.name, b.date
FROM battle b
WHERE b.id IN (
    SELECT lost_in_battle FROM ship WHERE name = 'Lettice'
)
AND b.id IN (
    SELECT lost_in_battle FROM ship WHERE name = 'HMS Atalanta'
);

SELECT Record_Company FROM orchestra WHERE Year_of_Founded < 2003
        INTERSECT
        SELECT Record_Company FROM orchestra WHERE Year_of_Founded > 2003;

SELECT student_id FROM Friend
INTERSECT
SELECT liked_id FROM Likes;

SELECT DISTINCT o.state
FROM Owners o
INNER JOIN Professionals p ON o.state = p.state;

SELECT state FROM Owners
INTERSECT
SELECT state FROM Professionals;

SELECT AVG(D.age)
FROM Dogs D
JOIN Treatments T ON D.dog_id = T.dog_id;

SELECT AVG(CAST(d.age AS REAL))
FROM Dogs d
WHERE d.dog_id IN (SELECT dog_id FROM Treatments);

SELECT role_code, street, city, state
FROM Professionals
WHERE city LIKE '%West%';

SELECT role_code, street, city, state
    FROM Professionals
    WHERE city LIKE '%West%';

SELECT first_name, last_name, email_address
FROM Owners
WHERE state LIKE '%North%';

SELECT name, age, weight
FROM Dogs
WHERE abandoned_yn = '1';

SELECT Citizenship FROM singer WHERE Birth_Year < 1945
INTERSECT
SELECT Citizenship FROM singer WHERE Birth_Year > 1955;
